on_receipts_with_audit','issue_receipt_with_audit','issue_receipt')) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) f where f.schema='public' and f.name='void_receipt_with_audit';
 if v_actual not in('[{"schema":"public","name":"void_receipt_with_audit","args":"p_receipt_id uuid, p_actor uuid, p_supporter_id uuid","allargs":"p_receipt_id uuid, p_actor uuid, p_supporter_id uuid DEFAULT NULL::uuid","defaults":1,"default_expression":"NULL::uuid","result":"TABLE(receipt_id uuid, pdf_url text)","owner":"postgres","acl":"{postgres=X/postgres,service_role=X/postgres}","full_acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"config":["search_path=\"\""],"definer":true,"language":"plpgsql","kind":"f","cost":100,"rows":1000,"strict":false,"leakproof":false,"parallel":"u","volatility":"v","support":"-","variadic":"-","modes":["i","i","i","t","t"],"body":"c120cd972f5c6bcb9ad822b1e61b1168","definition":"6e159b4b6d2b50514401d99e3dd54b7b"}]'::jsonb) then
 execute $definition$create or replace function public.void_receipt_with_audit(
  p_receipt_id uuid,
  p_actor uuid,
  p_supporter_id uuid default null
)
returns table (receipt_id uuid, pdf_url text)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_receipt public.receipt%rowtype;
  v_voided_at timestamptz;
begin
  perform 1 from auth.users u
  where u.id = p_actor
    and u.email_confirmed_at is not null
    and (u.banned_until is null or u.banned_until <= pg_catalog.clock_timestamp())
  for share;
  if not found then
    raise exception 'receipt_void_admin_required' using errcode = '42501';
  end if;

  perform 1 from public.admin_user a
  where a.auth_user_id = p_actor
    and a.status = 'active'
    and a.role in ('treasurer', 'admin')
  for share;
  if not found then
    raise exception 'receipt_void_admin_required' using errcode = '42501';
  end if;

  select * into v_receipt
  from public.receipt
  where id = p_receipt_id
  for update;
  if not found or v_receipt.status <> 'issued' then
    raise exception 'receipt_not_issued' using errcode = '22023';
  end if;
  if p_supporter_id is not null and p_supporter_id <> v_receipt.supporter_id then
    raise exception 'receipt_supporter_mismatch' using errcode = '22023';
  end if;

  v_voided_at := pg_catalog.clock_timestamp();
  update public.receipt
  set status = 'void', voided_at = v_voided_at, voided_by = p_actor
  where id = v_receipt.id;

  insert into public.audit_log(actor_user_id, action, entity, entity_id, detail)
  values (
    p_actor, 'receipt.void', 'receipt', v_receipt.id::text,
    pg_catalog.jsonb_build_object(
      'voidedAt', v_voided_at,
      'supporterId', v_receipt.supporter_id,
      'reason', 'manual'
    )
  );

  return query select v_receipt.id, v_receipt.pdf_url;
end;
$$;
